from mk import *
from lib import fbd
STRICT["on"] = True
PTS = [(0.01, 0.13), (0.02, 0.16), (0.03, 0.26), (0.04, 0.44), (0.05, 0.53), (0.06, 0.56)]
n = 6; xm = sum(p[0] for p in PTS) / n; ym = sum(p[1] for p in PTS) / n
slope = sum((x - xm) * (y - ym) for x, y in PTS) / sum((x - xm) ** 2 for x, _ in PTS)

def fig():
    g = Fig(560, 330, "מכונת אטווד: שני סלים A ו-B תלויים משני צדי גלגלת, A בגובה h מעל הרצפה. טבלת ניסוי 1: גובה, זמן ותאוצה. גרף ניסוי 2: התאוצה כפונקציה של הפרש המסות")
    g.ceiling(40, 200, 20); g.line(120, 20, 120, 40, width=1.5); g.pulley(120, 58, 20)
    g.line(100, 58, 100, 90, width=1.5); g.line(140, 58, 140, 200, width=1.5)
    g.path("M 82,100 Q 100,130 118,100 Z", fill="var(--d-fill)"); g.text(100, 120, "A", cls="dim")
    g.path("M 122,210 Q 140,240 158,210 Z", fill="var(--d-fill)"); g.text(140, 230, "B", cls="dim")
    g.ground(40, 200, 244); g.dim(66, 112, 66, 244, "h")
    x0, y0 = 30, 262
    g.rect(x0, y0, 200, 64, fill="none", width=1.5)
    for r in (16, 32, 48): g.line(x0, y0 + r, x0 + 200, y0 + r, width=0.8)
    g.text(x0 + 33, y0 + 12, "h (m)", cls="dim"); g.text(x0 + 100, y0 + 12, "t (s)", cls="dim"); g.text(x0 + 167, y0 + 12, "a (m/s²)", cls="dim")
    for i, (h, t, a) in enumerate([(0.5, 1.01, 0.98), (1, 1.40, 1.02), (1.5, 1.72, 1.01)]):
        y = y0 + 28 + i * 16
        g.text(x0 + 33, y, f"{h:g}", cls="dim"); g.text(x0 + 100, y, f"{t:.2f}", cls="dim"); g.text(x0 + 167, y, f"{a:.2f}", cls="dim")
    X, Y = g.graph(300, 290, 220, 230, "mA−mB (kg)", "a (m/s²)", xticks=[(v / 100, f"{v/100:g}") for v in (2, 4, 6)], yticks=[(v / 10, f"{v/10:g}") for v in range(1, 8)], xmax=0.07, ymax=0.7)
    for x, y in PTS: g.dot(X(x), Y(y))
    g.plot(X, Y, [(0.01, 0.1), (0.06, 0.6)], width=1.6)
    return g

def basket(lab, T, W, pos, note):
    return lambda: fbd([("T", 90, T), (f"m_{lab} g", -90, W)], f"תרשים כוחות על הסל {lab}: מתיחות החוט כלפי מעלה, וכוח הכובד כלפי מטה. הכיוון החיובי " + ("כלפי מטה" if pos < 0 else "כלפי מעלה"),
                       positive=pos, body="block", body_label=lab, note=note)

E(id="bagrut-2016-q2", year=2016, label="2016 שאלה 2", topic="dynamics", sub="dyn-systems", diff=3, fig=fig,
  stem=r"לפניכם שני קטעים מדוח מעבדה של צוות תלמידים. קטע א. נושא הניסוי: יישום החוק השני של ניוטון. המערכת (\"מכונת אטווד\") בנויה מגלגלת שמחוברת לתקרה, ועליה עובר חוט. בשני קצות החוט קשורים סלים $A$ ו-$B$, ובהם משקולות. מסת הסל $A$ עם המשקולות היא $m_A$, ומסת הסל $B$ עם המשקולות היא $m_B$. הסל $A$, הכבד יותר, נמצא בגובה $h$ מעל הרצפה. מסת החוט והגלגלת והחיכוך זניחים. משחררים את המערכת ממנוחה, ומודדים בשעון עצר את זמן התנועה $t$, מהשחרור ועד שהסל $A$ פוגע ברצפה. ניסוי 1: המטרה היא לאמת את ההשערה שהסל $A$ יורד בתאוצה קבועה. שחררו את הסל $A$ כמה פעמים, בכל פעם מגובה אחר, בלי לשנות את מסות הסלים. התוצאות בטבלה.",
  parts=[
    P("א", r"הסבירו בקצרה למה, לפי חוקי ניוטון, נכון להניח שהסל $A$ יורד בתאוצה קבועה. אל תסתמכו על תוצאות המדידות.", OPEN, ["principle"], [
        X(r"בוחרים לסל A כלפי מטה כחיובי, ולסל B כלפי מעלה, כדי שלשניהם תהיה אותה תאוצה עם אותו סימן."),
        S(r"הכוחות קבועים", r"משקלי הסלים לא משתנים בזמן התנועה. גם המתיחות קבועה", r"m_A g,\ \ m_B g,\ \ \Delta T = 0"),
        S(r"משוואות הכוחות", r"לסל A: הכובד פחות המתיחות. לסל B: המתיחות פחות הכובד. מחברים, והמתיחות מתבטלת", r"(m_A - m_B)\,g = (m_A + m_B)\,a", eq=r"\Sigma\vec F = m\vec a"),
        S(r"מחלקים את משוואת הכוחות במסה", r"כוח קבוע חלקי מסה קבועה נותן תאוצה קבועה", r"a = \frac{(m_A - m_B)\,g}{m_A + m_B}"),
    ], r"הכוח השקול קבוע והמסה קבועה, ולכן התאוצה קבועה", key=r"הכוח השקול קבוע"),
    P("ב", r"איך חישבו התלמידים את התאוצה בניסוי הזה?", choice([r"$a = \frac{2h}{t^2}$", r"$a = \frac{h}{t^2}$", r"$a = \frac{h}{t}$", r"$a = \frac{2h}{t}$"], 0), ["principle", "algebra"], [
        S(r"תנועה ממנוחה בתאוצה קבועה", r"הגובה והזמן נמדדו, והתאוצה היא הנעלם", r"h = 0 + 0 \cdot t + \tfrac{1}{2} a t^2", eq=r"x = x_0 + v_0 t + \tfrac{1}{2}at^2"),
        S(r"מבודדים את התאוצה", r"מכפילים בשתיים ומחלקים בריבוע הזמן", r"a = \frac{2h}{t^2}"),
        C(r"בדיקה בשורה הראשונה של הטבלה", r"מציבים גובה וזמן מהטבלה", r"\frac{2 \cdot 0.5}{1.01^2} \approx 0.98\,\text{m/s}^2 \;\checkmark"),
    ], r"$a = 2h/t^2$", key=r"a = 2h/t²"),
    P("ג", r"האם התוצאות בטבלה מבססות את ההשערה שהסל $A$ יורד בתאוצה קבועה? נמקו.", choice(["כן", "לא"], 0), ["graph"], [
        S(r"התאוצות שהתקבלו", r"בשלושה גבהים שונים, לפי הנוסחה מסעיף ב", r"0.98,\ \ 1.02,\ \ 1.01\ \text{m/s}^2"),
        S(r"הפיזור", r"הסטייה מהממוצע בערך שני אחוזים, וזה בתחום של שגיאת מדידה", r"\pm 2\%"),
    ], r"כן: התאוצות כמעט זהות (סטייה של כ-$2\%$)", key=r"כן"),
    P("ד", r"קטע ב, ניסוי 2: המטרה היא לבדוק איך התאוצה תלויה בהפרש המסות של הסלים, כשהמסה הכוללת של המערכת לא משתנה. חזרו על המדידה כמה פעמים, ובכל פעם העבירו משקולות מהסל $B$ לסל $A$. המדידות וקו המגמה מוצגים בגרף. שרטטו את תרשים הכוחות על כל אחד מהסלים, וכתבו ליד כל כוח את שמו.", OPEN, ["fbd"], [
        S(r"על כל סל", r"כוח הכובד כלפי מטה, ומתיחות החוט כלפי מעלה. המתיחות שווה בשני הצדדים, כי החוט והגלגלת קלים", r"m_A g,\ T \qquad m_B g,\ T"),
        D(r"תרשים הכוחות על הסל A", basket("A", 0.9, 1.1, -90, "יורד")),
        D(r"תרשים הכוחות על הסל B", basket("B", 0.9, 0.7, 90, "עולה")),
    ], r"על כל סל: כוח הכובד ומתיחות החוט"),
    P("ה", r"פתחו, לפי חוקי ניוטון, משוואה שמקשרת בין התאוצה להפרש המסות של הסלים.", choice([r"$a = \frac{g}{m_A + m_B}(m_A - m_B)$", r"$a = \frac{g}{m_A - m_B}(m_A + m_B)$", r"$a = g(m_A - m_B)$", r"$a = \frac{g}{m_A}(m_A - m_B)$"], 0), ["fbd", "principle", "algebra"], [
        S(r"משוואות הכוחות", r"לסל A כלפי מטה חיובי, ולסל B כלפי מעלה", r"m_A g - T = m_A a \qquad T - m_B g = m_B a", eq=r"\Sigma\vec F = m\vec a"),
        S(r"מחברים", r"המתיחות מתבטלת", r"(m_A - m_B)\,g = (m_A + m_B)\,a"),
        S(r"מחלקים את משוואת הכוחות במסה", r"מחלקים במסה הכוללת", r"a = \frac{g}{m_A + m_B}\,(m_A - m_B)"),
    ], r"$a = \frac{g}{m_A + m_B}(m_A - m_B)$", key=r"a = g(mA−mB)/(mA+mB)"),
    P("ו", r"לפי הגרף שבקטע ב והמשוואה מסעיף ה, מה המסה הכוללת $(m_A + m_B)$ של הסלים? פרטו.", num(10 / slope, "kg", tol=10), ["graph", "algebra"], [
        S(r"השיפוע של קו המגמה", r"לוקחים שתי נקודות רחוקות על הקו", r"\frac{0.6 - 0.1}{0.06 - 0.01} = 10\,\tfrac{\text{m/s}^2}{\text{kg}}"),
        S(r"משווים לביטוי", r"לפי סעיף ה, השיפוע הוא תאוצת הכובד חלקי המסה הכוללת", r"\frac{g}{m_A + m_B} = 10 \;\Rightarrow\; m_A + m_B = \frac{10}{10} = 1\,\text{kg}"),
    ], r"$\approx 1\,\text{kg}$", key=r"mA+mB=1 kg"),
  ],
  concepts=["מכונת אטווד", "אימות תאוצה קבועה", "קו מגמה", "שיפוע", "מסה כוללת קבועה"],
  summary=r"דוח מעבדה על מכונת אטווד: מאמתים שהתאוצה קבועה, ומגרף תאוצה מול הפרש המסות מוצאים את המסה הכוללת.",
  review="הנחה שלי.\nבסעיף ו הסבילות עשרה אחוזים, כי השיפוע תלוי בקו המגמה שהתלמיד מעביר. בסעיפים ב ו-ה התלמיד בוחר את הביטוי הנכון מתוך ארבעה.\nמה לבדוק: רק לאשר.")
